package com.tripmateai.service.impl; import com.tripmateai.dto.request.group.*; import com.tripmateai.dto.response.group.*; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.GroupExpenseService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class GroupExpenseServiceImpl implements GroupExpenseService {private final GroupRepository groups;private final GroupMemberRepository members;private final GroupExpenseRepository expenses;private final GroupExpenseShareRepository shares;private final TripRepository trips;private final UserRepository users;private User me(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,me()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not own this trip"):new ResourceNotFoundException("Trip not found"));} private Group group(Long id){return groups.findByTrip(trip(id)).orElseThrow(()->new ResourceNotFoundException("Trip group not found"));} private GroupMember member(Group g,Long id){return members.findById(id).filter(x->x.getGroup().getId().equals(g.getId())).orElseThrow(()->new BadRequestException("Invalid group member"));} private GroupMemberResponse map(GroupMember m){return new GroupMemberResponse(m.getId(),m.getUser().getId(),m.getUser().getFullName(),m.getMemberRole());} private GroupResponse map(Group g){return new GroupResponse(g.getId(),g.getName(),members.findByGroup(g).stream().map(this::map).toList());}
 public GroupResponse create(Long id,CreateGroupRequest r){var t=trip(id);if(groups.findByTrip(t).isPresent())throw new BadRequestException("A group already exists for this trip");var g=new Group();g.setTrip(t);g.setName(r.name());g=groups.save(g);var owner=new GroupMember();owner.setGroup(g);owner.setUser(me());owner.setMemberRole("OWNER");members.save(owner);return map(g);} @Transactional(readOnly=true) public GroupResponse get(Long id){return map(group(id));} public GroupMemberResponse add(Long id,AddGroupMemberRequest r){var g=group(id);var u=users.findById(r.userId()).orElseThrow(()->new ResourceNotFoundException("User not found"));if(members.findByGroupAndUser(g,u).isPresent())throw new BadRequestException("User is already a group member");var m=new GroupMember();m.setGroup(g);m.setUser(u);return map(members.save(m));} public void remove(Long id,Long userId){var g=group(id);var u=users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found"));var m=members.findByGroupAndUser(g,u).orElseThrow(()->new ResourceNotFoundException("Group member not found"));if("OWNER".equals(m.getMemberRole()))throw new BadRequestException("Trip owner cannot be removed");members.delete(m);} @Transactional(readOnly=true) public List<GroupExpenseResponse> expenses(Long id){return expenses.findByGroup(group(id)).stream().map(this::mapExpense).toList();}
 public GroupExpenseResponse createExpense(Long id,CreateGroupExpenseRequest r){var g=group(id);if(new HashSet<>(r.participantMemberIds()).size()!=r.participantMemberIds().size())throw new BadRequestException("Duplicate participants are not allowed");var payer=member(g,r.paidByMemberId());var participants=r.participantMemberIds().stream().map(x->member(g,x)).toList();var amount=r.amount().setScale(2,RoundingMode.HALF_UP);var count=BigDecimal.valueOf(participants.size());var base=amount.divide(count,2,RoundingMode.DOWN);var remainder=amount.subtract(base.multiply(count));var e=new GroupExpense();e.setGroup(g);e.setPaidBy(payer);e.setDescription(r.description());e.setAmount(amount);e=expenses.save(e);for(int i=0;i<participants.size();i++){var s=new GroupExpenseShare();s.setGroupExpense(e);s.setGroupMember(participants.get(i));s.setAmount(base.add(i==0?remainder:BigDecimal.ZERO));shares.save(s);}return mapExpense(e);} private GroupExpenseResponse mapExpense(GroupExpense e){var ss=shares.findAll().stream().filter(x->x.getGroupExpense().getId().equals(e.getId())).map(x->new GroupExpenseResponse.ShareResponse(x.getGroupMember().getId(),x.getAmount())).toList();return new GroupExpenseResponse(e.getId(),e.getDescription(),e.getAmount(),e.getPaidBy().getId(),ss);}
 @Transactional(readOnly=true) public List<GroupBalanceResponse> balances(Long id){var g=group(id);var all=expenses.findByGroup(g);return members.findByGroup(g).stream().map(m->{var paid=all.stream().filter(e->e.getPaidBy().getId().equals(m.getId())).map(GroupExpense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);var owed=shares.findAll().stream().filter(s->s.getGroupMember().getId().equals(m.getId())).map(GroupExpenseShare::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new GroupBalanceResponse(m.getId(),m.getUser().getFullName(),paid,owed,paid.subtract(owed));}).toList();} @Transactional(readOnly=true) public List<SettlementResponse> settlements(Long id){var b=balances(id);var creditors=new ArrayList<>(b.stream().filter(x->x.netBalance().signum()>0).toList());var debtors=new ArrayList<>(b.stream().filter(x->x.netBalance().signum()<0).toList());var out=new ArrayList<SettlementResponse>();int i=0,j=0;var cr=creditors.stream().map(GroupBalanceResponse::netBalance).toArray(BigDecimal[]::new);var db=debtors.stream().map(x->x.netBalance().abs()).toArray(BigDecimal[]::new);while(i<debtors.size()&&j<creditors.size()){var x=db[i].min(cr[j]);out.add(new SettlementResponse(debtors.get(i).memberId(),creditors.get(j).memberId(),x));db[i]=db[i].subtract(x);cr[j]=cr[j].subtract(x);if(db[i].signum()==0)i++;if(cr[j].signum()==0)j++;}return out;}}
